    "body": "float e=smoothstep(.30,.47,q)*(1.-smoothstep(.87,1.,q));vec4 v=er4Gather(p,vec2(0.,.12),q,.40,.62,7.,0.);for(int layer=0;layer<3;layer++){float z=float(layer),speed=mix(3.75,7.05,z*.5);for(int i=0;i<19;i++){float k=float(i)+z*19.,seed=k+71.;float life=fract(hash(vec2(k,23.))+q*speed);float x=mix(-.86,.69,hash(vec2(k,17.)));vec2 dir=normalize(vec2(.32+.12*sin(k*1.7),-1.));vec2 c=vec2(x+.52*(life-.5),mix(.98,-.98,life));float l=mix(.095,.26,z*.5)*(.65+.60*hash(vec2(k,51.))),w=l*.28;float a=e*smoothstep(0.,.13,life)*(1.-smoothstep(.86,1.,life))*(.54+.23*z);float edge=(1.-smoothstep(.85,.99,abs(p.x)))*(1.-smoothstep(.85,.99,abs(p.y)));if(length(p-c)>l+.64)continue;float d=seg(p,c-dir*(.24+.16*z),c-dir*l*.27);float halo=exp(-d/(.037+.012*z))*a*edge;float core=exp(-d/(.006+.003*z))*a*edge;v=over(v,vec4(.25,.67,1.,sat(halo*.65)));v=over(v,vec4(.84,.97,1.,sat(core*.95)));vec2 side=vec2(-dir.y,dir.x),delta=p-c,uv=vec2(dot(delta,side)/w,dot(delta,dir)/(l*.5));float diamond=abs(uv.x)+abs(uv.y),mask=1.-smoothstep(.93,1.04,diamond);float ridge=exp(-abs(uv.x-.13*sin(seed))/.085),rim=exp(-abs(diamond-.96)/.09),shine=exp(-pow((uv.y+uv.x*.22-.65*cos(t*TAU*2.+seed))/.15,2.));vec3 col=mix(vec3(.23,.46,.76),vec3(.68,.89,1.),smoothstep(-.10,.10,uv.x));col=mix(col,vec3(.98,1.,1.),sat(ridge*.83+rim*.78+shine*.65));float aura=exp(-max(0.,diamond-1.)*5.)*(1.-mask)*a*edge;v=over(v,vec4(.39,.78,1.,aura*.44));v=over(v,vec4(col,mask*a*edge));}}for(int i=0;i<24;i++){float k=float(i),f=fract(hash(vec2(k,91.))+q*7.8);vec2 c=vec2(mix(-.78,.78,hash(vec2(k,17.)))+.20*(f-.5),mix(.90,-.90,f));vec2 dir=normalize(vec2(.35,-1.));float d=seg(p,c-dir*.09,c);float a=e*sin(3.14159*f)*exp(-d/.007)*(1.-smoothstep(.85,.99,abs(p.x)))*(1.-smoothstep(.85,.99,abs(p.y)));v=over(v,vec4(.82,.95,1.,a*.64));}return v;"
