const earthHelpers="\nconst float e2Form=1.;\nfloat e2Grow(float q){return mix(smoothstep(.02,.91,q),1.,e2Form);}\nfloat e2Time(float t,float q){return e2Form<.5&&q>=1.?0.:fract(t);}\nfloat e2Noise(vec2 p,float t){return fb(p+dir2(TAU*t)*.74);}\n\nfloat quakeEase(float f){return 1.-pow(1.-sat(f),3.);}\nfloat earthEnv(float q,float a,float b){return smoothstep(a,a+.035,q)*(1.-smoothstep(b,1.,q));}\nvec4 stoneShape(vec2 p,vec2 c,vec2 r,float ang,float seed,float heat){\n if(min(r.x,r.y)<.006)return vec4(0.);\n vec2 v=p-c;v=vec2(dot(v,dir2(ang)),dot(v,dir2(ang+1.5707963)))/r;\n if(max(abs(v.x),abs(v.y))>1.25)return vec4(0.);\n float dist=-10.;for(int i=0;i<8;i++){float k=float(i);vec2 n=dir2(k*TAU/8.+.22*hash(vec2(k,seed)));dist=max(dist,dot(v,n)-(.74+.17*hash(vec2(k,seed+8.))));}\n float mask=1.-smoothstep(-.025,.035,dist);\n float best=10.,second=10.;vec2 site=vec2(0.);\n for(int i=0;i<6;i++){float k=float(i);vec2 z=dir2(k*TAU/6.+.36*hash(vec2(k,seed+11.)))*(.34+.35*hash(vec2(k,seed+4.)));float dd=length(v-z);if(dd<best){second=best;best=dd;site=z;}else second=min(second,dd);}\n float face=clamp(.52+.51*dot(site,normalize(vec2(-.65,.76))),.12,.97);\n float grain=fb(v*13.+seed);float bevel=smoothstep(-.18,-.02,dist);\n vec3 col=mix(vec3(.105,.085,.068),vec3(.73,.64,.49),face*.82+grain*.12);\n col=mix(col,col*.60,bevel*sat(.52+v.x*.34-v.y*.28));\n float joint=1.-smoothstep(.009,.047,second-best);\n col=mix(col,col*.48,joint*.38);\n vec3 molten=mix(vec3(.29,.024,.008),vec3(1.,.72,.19),joint*.83+grain*.17);\n col=mix(col,mix(col*.35,molten,.26+.74*joint),sat(heat));\n return vec4(col,mask);\n}\n\nvec4 soilDust(vec2 p,vec2 c,vec2 r,float t,float seed,float hot){\n vec2 v=(p-c)/max(r,vec2(.02));if(length(v)>1.5)return vec4(0.);\n float n=e2Noise(v*3.4+seed,t),detail=e2Noise(v*8.+seed*1.71,t);\n float d=length(v)+(.5-n)*.68;float a=(1.-smoothstep(.48,1.22,d))*(.44+.56*detail);\n float shade=clamp(.45+.25*v.y-.19*v.x+.29*n,0.,1.);\n vec3 col=mix(vec3(.19,.125,.074),vec3(.85,.70,.48),shade);\n col=mix(col,mix(vec3(.075,.062,.055),vec3(.54,.31,.18),shade),hot);\n return vec4(col,a*.86);\n}\n\nvec4 grit(vec2 p,vec2 c,float f,float r,float seed,float count,float heat){\n if(f<=0.||f>=1.)return vec4(0.);vec4 col=vec4(0.);\n for(int i=0;i<24;i++){float k=float(i);if(k>=count*uDensity)break;float a=TAU*hash(vec2(k,seed));float speed=.35+.65*hash(vec2(k,seed+7.));\n vec2 v=c+vec2(cos(a)*r*speed*f,sin(a)*r*.34*speed*f+4.*f*(1.-f)*r*(.18+.46*hash(vec2(k,seed+3.))));\n float sz=(.012+.039*hash(vec2(k,seed+5.)))*(1.-.35*f);\n vec4 w=stoneShape(p,v,vec2(sz,sz*.75),k+f*5.,k+seed,heat);w.a*=smoothstep(0.,.04,f)*(1.-smoothstep(.55,1.,f));col=over(col,w);}\n return col;\n}\n\nvec4 earthCharge(vec2 p,vec2 c,float q,float r){\n float f=phase(q,0.,.35);vec4 col=vec4(0.);\n for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.+f*.7;vec2 v=c+dir2(a)*r*(1.-f);vec4 w=stoneShape(p,v,vec2(.022,.018),k+q*3.,k+11.,0.);w.a*=gate(q,0.,.43);col=over(col,w);}return col;\n}\nvec4 earthShock(vec2 p,vec2 c,float f,float r,float force){\n if(f<=0.||f>=1.)return vec4(0.);float radius=.035+r*quakeEase(f),d=length((p-c)/vec2(1.,.34));\n float a=exp(-abs(d-radius)/(.027+.018*f))*sin(3.14159*f)*force;return vec4(vec3(.88,.72,.47),sat(a));\n}\nvec4 groundPatch(vec2 p,vec2 c,vec2 r,float t,float seed,float wet){\n vec2 v=(p-c)/max(r,vec2(.02));float n=fb(v*5.+seed),fine=fb(v*21.+seed);\n float d=length(v)+(.5-n)*.21;float mask=1.-smoothstep(.86,1.05,d);\n float layer=sin(v.y*15.+n*4.);vec3 dry=mix(vec3(.17,.105,.054),vec3(.64,.48,.29),.18+.64*n+.13*fine);\n float ripple=pow(.5+.5*sin(v.x*8.+v.y*19.+n*4.-t*TAU),8.);\n vec3 mud=mix(vec3(.14,.12,.074),vec3(.51,.43,.24),.24+.47*n+.19*ripple);\n vec3 col=mix(dry,mud,wet);col*=.80+.20*smoothstep(-1.,.7,v.y)+.08*layer*(1.-wet);\n return vec4(col,mask*.97);\n}\n\nvec4 fissure(vec2 p,vec2 c,float g,float extent,float seed,float hot,float width){\n if(g<=0.)return vec4(0.);float d=10.;\n for(int i=0;i<7;i++){float k=float(i),a=k*TAU/7.+.43*hash(vec2(k,seed));vec2 v=dir2(a)*vec2(extent,extent*.34)*g;\n vec2 last=c;for(int j=1;j<=5;j++){float u=float(j)/5.;vec2 next=c+v*u+vec2(.073*sin(k*3.+u*23.+seed),.028*cos(k+u*17.))*g*u;d=min(d,seg(p,last,next));if(j==3)d=min(d,seg(p,next,next+dir2(a+.95)*vec2(.20,.068)*g));last=next;}}\n float w=width*(.55+.65*fb(p*13.+seed));float core=1.-smoothstep(w,w+.009,d),lip=exp(-abs(d-w-.014)/.009);\n return over(vec4(vec3(.66,.46,.25),lip*.85),vec4(mix(vec3(.032,.021,.015),vec3(1.,.32,.027),hot),core));\n}\n\nvec4 gem(vec2 p,vec2 a,vec2 b,float w,float seed){\n vec2 d=b-a;float l=length(d);if(l<.009||w<.006)return vec4(0.);\n vec2 ax=d/l,side=vec2(-ax.y,ax.x),v=p-a;float y=dot(v,ax)/l,x=dot(v,side);\n float width=w*min(sat(y*5.),sat((1.-y)*3.4));float m=(1.-smoothstep(width-.004,width+.005,abs(x)))*smoothstep(-.01,.025,y)*(1.-smoothstep(.98,1.008,y));\n float u=x/max(width,.006);float ridge=.23*sin(seed),plane=step(ridge,u),facet=step(.55,abs(u));\n vec3 col=mix(vec3(.16,.25,.46),vec3(.64,.86,.99),plane*.70+.15);col=mix(col,vec3(.31,.39,.69),facet*.49);\n float glint=exp(-pow((u-ridge)*17.,2.))*.72+exp(-pow((abs(u)-.94)*23.,2.))*.53;\n float inclusions=pow(.5+.5*sin(y*31.+u*7.+seed),14.)*.16;\n col=mix(col,vec3(.98,.99,1.),sat(glint+inclusions));return vec4(col,m*(.72+.26*sat(glint+facet*.5)));\n}\n\nvec4 crystalCluster(vec2 p,vec2 c,float g,float height,float width,float count,float seed){\n vec4 v=vec4(0.);for(int i=0;i<12;i++){float k=float(i);if(k>=count)break;float x=(k-(count-1.)*.5)/max(1.,count-1.);\n float grow=phase(g,.045*k,.83+.014*k);vec2 a=c+vec2(x*width,.045*cos(k*2.4+seed));vec2 b=a+vec2(x*.27,(.52+.48*hash(vec2(k,seed)))*height)*grow;\n v=over(v,gem(p,a,b,.115*grow*(.63+.37*hash(vec2(k,seed+1.))),k+seed));}return v;\n}\n\nvec4 rockWall(vec2 p,float g,float width,float height,float hot,float cut){\n vec4 col=vec4(0.);for(int depth=0;depth<2;depth++){float z=float(depth);for(int i=0;i<5;i++){float k=float(i);for(int j=0;j<7;j++){float h=float(j);\n float e=phase(g,k*.14+h*.012,.35+k*.14+h*.012);if(e>.001){float x=(h-3.)*.23*width+.055*mod(k,2.)+(1.-z)*.09,y=-.65+k*.235*height+(1.-z)*.12;\n vec2 rr=vec2(.148*width,.147*height)*e;vec4 v=stoneShape(p,vec2(x,y),rr,.12*sin(h+k),h+k*7.+z*35.,hot);v.rgb*=.63+.37*z;v.a*=cut;col=over(col,v);}}}}return col;\n}\n\nvec4 earthFlow(vec2 p,float f,float t,float height,float breadth,float wet,float hot){\n if(f<=0.||f>=1.)return vec4(0.);float x=mix(-.93,.96,f),rel=p.x-x;\n float e=smoothstep(0.,.10,f)*(1.-smoothstep(.86,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<3;i++){float k=float(i),z=k/2.;float ground=-.47-.19*z;float n=e2Noise(vec2(rel*8.,p.y*9.+k*7.),t);\n float ridge=exp(-pow((rel+.17+.08*k)/max(.1,breadth*.75),2.));\n float top=ground+height*(.63+.37*z)*ridge+.09*(n-.5);\n float mask=smoothstep(ground-.10,ground+.02,p.y)*(1.-smoothstep(top-.027,top+.031,p.y))*smoothstep(-breadth*1.65,-breadth,rel)*(1.-smoothstep(-.02,.12,rel));\n float streak=pow(.5+.5*sin(rel*17.+p.y*23.+n*8.-t*TAU*2.),5.);\n vec3 col=mix(vec3(.19,.11,.048),vec3(.72,.53,.32),.17+.50*n+.18*streak);\n col=mix(col,mix(vec3(.12,.09,.062),vec3(.59,.46,.31),.26+.44*n+.23*streak),wet);\n float molten=1.-smoothstep(.04,.19,abs(noise(vec2(rel*8.,p.y*10.)+dir2(t*TAU)*.65)-.5));\n col=mix(col,mix(vec3(.16,.055,.025),vec3(1.,.60,.07),molten),hot);\n col*=.68+.32*z;v=over(v,vec4(col,mask*e*.98));\n for(int j=0;j<6;j++){float h=float(j),seed=k*13.+h,rnd=hash(vec2(seed,13.));float rr=(.029+.055*rnd)*(1.-.28*wet);vec2 c=vec2(x-breadth*(.16+.78*rnd),ground+height*.55*hash(vec2(seed,9.)));vec4 w=stoneShape(p,c,vec2(rr,rr*.79),seed+t*TAU,seed+17.,hot);w.a*=e;v=over(v,w);}\n }return v;\n}\n\nvec4 rockFall(vec2 p,float q,float t,float count,float size,float start,float heat,float lateral){\n vec4 col=vec4(0.);for(int i=0;i<12;i++){float k=float(i);if(k>=count)break;float begin=start+k*.035,f=phase(q,begin,begin+.27);\n float x=(hash(vec2(k,13.))-.5)*1.24;vec2 a=vec2(x-lateral*.32,.76),b=vec2(x+lateral*.22,-.60);\n float ch=phase(q,.01,begin);vec2 c=mix(a,b,f*f);float r=size*(.73+.27*hash(vec2(k,17.)))*ch;\n if(q<begin+.27){if(heat>.1){for(int j=0;j<4;j++){float z=float(j);vec4 w=soilDust(p,c+normalize(a-b)*(.06+z*.055),vec2(r*(1.1-.13*z),r*(1.25-.12*z)),t,k+z,1.);w.a*=smoothstep(.02,.23,f)*(1.-z*.15);col=over(col,w);}}vec4 w=stoneShape(p,c,vec2(r,r*.78),k+f*2.,k+15.,heat);w.a*=smoothstep(0.,.07,q)*(1.-smoothstep(.91,1.,f));col=over(col,w);}\n float hit=phase(q,begin+.27,min(.995,begin+.58));vec4 dust=soilDust(p,b+vec2(0.,.14*hit),vec2(.06+.29*hit,.04+.15*hit),t,k,heat);dust.a*=sin(3.14159*hit);col=over(col,dust);col=over(col,grit(p,b,hit,.28+size,k+21.,9.,heat));col=over(col,earthShock(p,b,hit,.34+size,.95));}return col;\n}\n\nvec4 sandVortex(vec2 p,float t,float g,float radius,float height,float hole){\n if(g<=.001)return vec4(0.);vec4 v=vec4(0.);float y=(p.y+.62)/max(.02,height*g);\n float w=(.21+.70*pow(sat(y),.85))*radius*g;float x=p.x-.044*sin(y*8.+t*TAU*2.);\n float mask=smoothstep(-.03,.06,y)*(1.-smoothstep(.92,1.04,y))*(1.-smoothstep(.86,1.08,abs(x)/max(.01,w)));\n float n=e2Noise(vec2(x*14.,y*12.),t);float depth=sqrt(max(0.,1.-pow(x/max(.01,w),2.)));\n float rear=pow(.5+.5*sin(y*TAU*4.-t*TAU*4.+acos(clamp(x/max(.01,w),-1.,1.))),5.);\n float front=pow(.5+.5*sin(y*TAU*4.-t*TAU*4.-acos(clamp(x/max(.01,w),-1.,1.))),4.);\n v=vec4(mix(vec3(.31,.19,.085),vec3(.88,.72,.42),n*.40+front*.45),mask*(.16+.24*rear+.56*front*depth));\n for(int i=0;i<28;i++){float k=float(i),f=fract(t+hash(vec2(k,5.))),a=t*TAU*3.+k*2.4;vec2 c=vec2(cos(a)*radius*(.23+.66*f)*g,-.62+height*f*g);vec4 w0=stoneShape(p,c,vec2(.012,.008),a,k,0.);w0.a*=sin(3.14159*f)*(.45+.55*step(0.,sin(a)));v=over(v,w0);}return v;\n}\n\nvec4 moltenFountain(vec2 p,float t,float q,float width,float height,float count){\n vec2 root=vec2(0.,-.67);float f=phase(q,.35,1.),g=quakeEase(phase(q,.35,.50));vec4 col=earthCharge(p,root,q,.43);\n float e=earthEnv(q,.35,.77);float y=(p.y-root.y)/max(.01,height*g),x=p.x-.04*sin(y*12.-t*TAU*4.);\n float n=fb(vec2(x*16.+t,y*8.-t*5.));float a=(1.-smoothstep(.68,1.1,abs(x)/max(.01,width*(.45+.55*sat(y)))))*smoothstep(-.03,.06,y)*(1.-smoothstep(.82,1.03,y));\n col=over(col,vec4(mix(vec3(.61,.055,.008),vec3(1.,.78,.10),n),a*e));\n for(int i=0;i<20;i++){float k=float(i);if(k>=count)break;float u=phase(f,.025*k,.96);vec2 c=root+vec2((hash(vec2(k,7.))-.5)*1.65*u,4.*u*(1.-u)*height*(.5+.5*hash(vec2(k,13.))));vec4 w=stoneShape(p,c,vec2(.035+.025*hash(vec2(k,11.)),.027),k+u*4.,k+8.,1.);w.a*=sin(3.14159*u);col=over(col,w);}return over(col,earthShock(p,root,f,.72,.95));\n}\n\nvec4 e2SandPit(vec2 p,float q,float t,float depth){\n float g=phase(q,.04,.50),e=earthEnv(q,.03,.81);vec2 c=vec2(0.,-.39),v=(p-c)/vec2(1.,.34);float r=length(v),a=atan(v.y,v.x);\n float n=e2Noise(v*12.,t);float band=pow(.5+.5*sin(a*5.+r*27.+t*TAU*3.),5.);\n float shade=smoothstep(.06,.36+depth*.12,r);vec3 col=mix(vec3(.10,.055,.023),mix(vec3(.40,.26,.10),vec3(.88,.69,.39),.45*n+.48*band),mix(.65,shade,depth));\n vec4 outv=vec4(col,(1.-smoothstep(.79*g,.86*g+.01,r))*e);\n for(int i=0;i<24;i++){float k=float(i),f=fract(t+hash(vec2(k,7.))),ang=k*2.39996+t*TAU;vec2 pos=c+dir2(ang)*vec2(.78,.78*.34)*g*(1.-f);float z=1.-smoothstep(.006,.014,length(p-pos));outv=over(outv,vec4(vec3(.90,.73,.43),z*sin(3.14159*f)*e));}return outv;\n}\nvec4 e2DustImpact(vec2 p,vec2 c,float f,float radius,float heat,float seed){\n if(f<=0.||f>=1.)return vec4(0.);vec4 v=vec4(0.);\n for(int i=0;i<7;i++){float k=float(i),a=k*TAU/7.;vec2 pos=c+dir2(a)*vec2(radius,radius*.34)*quakeEase(f)*.54+vec2(0.,.08+.19*f);vec4 w=soilDust(p,pos,vec2(.045+radius*f*.27,.03+radius*f*.18),f,k+seed,heat);w.a*=sin(3.14159*f);v=over(v,w);}return v;\n}\nvec4 e2MudPool(vec2 p,float t,float g,float radius,float seed,float depth){\n if(g<=.001)return vec4(0.);vec2 c=vec2(0.,-.44);vec4 v=groundPatch(p,c,vec2(radius,radius*.34)*g,t,seed,1.);\n for(int i=0;i<11;i++){float k=float(i);if(k>=5.+depth*6.)break;float f=fract(t+hash(vec2(k,seed)));vec2 pos=c+vec2((hash(vec2(k,seed+1.))-.5)*radius*1.65,(hash(vec2(k,seed+2.))-.5)*radius*.44)*g;\n float rr=(.025+.10*f*depth)*g;float z=ring(p,pos,vec2(rr,rr*.34),.004)*sin(3.14159*f);v=over(v,vec4(vec3(.66,.58,.31),sat(z*.5)*g));\n float bubble=1.-smoothstep(.008,.015,length(p-pos-vec2(0.,.022*sin(3.14159*f))));v=over(v,vec4(vec3(.72,.64,.37),bubble*sin(3.14159*f)*g));}return v;\n}\nvec4 e2SandField(vec2 p,float t,float g,float strength){\n vec4 v=vec4(0.);for(int i=0;i<9;i++){float k=float(i);if(k>=5.+4.*strength)break;float f=fract(t+hash(vec2(k,19.)));float a=phase(g,k*.045,.62+k*.042);vec2 c=vec2(-.92+1.84*f,-.52+k*.135*strength);vec4 w=soilDust(p,c,vec2(.42+.1*strength,.14+.11*strength),t,k,0.);w.a*=sin(3.14159*f)*a*.79;v=over(v,w);}\n for(int i=0;i<32;i++){float k=float(i);if(k>=22.+10.*strength)break;float f=fract(t*(1.+floor(strength+.5))+hash(vec2(k,7.)));vec2 c=vec2(-.93+1.86*f,-.62+( .68+.61*strength)*hash(vec2(k,13.)));float a=phase(g,hash(vec2(k,11.))*.3,.92);float z=1.-smoothstep(.004,.012,seg(p,c-vec2(.045+.035*strength,0.),c));v=over(v,vec4(vec3(.86,.69,.43),z*sin(3.14159*f)*a));}return v;\n}\n";
for(const r of records){const d=earthDetails[r.row];if(!d)continue;Object.assign(r,{duration:d.duration,loop:d.loop,note:"個別改修版："+d.note,refined:true});}
