    "body": "float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=lFast(phase(f,.37,.80));vec4 v=light(lpCharge(p,vec2(0.,.58),f,.33,.90,2.7)*.73);return over(v,lpAurora(p,ft,g));",
