    "body": "float g=phase(q,.04,.60),e=p3Fade(q);vec2 a=vec2(-.27,-.27),b=mix(a,vec2(.25,.30),g);vec4 v=p3Tube(p,a,b,.039,.016,1.,7.);v=over(v,branchLeaves(p,a,b,g,7.,1.5,0.));for(int i=0;i<3;i++){float k=float(i),f=phase(q,.38+k*.09,.69+k*.075);vec2 c=mix(a,vec2(.25,.30),.40+k*.20)+vec2(.049,-.10);v=over(v,berry(p,c,.075*f));}v.a*=e;return v;",
