    "body": "float g=p3Growth(q),tt=p3Time(t,q);vec4 v=vec4(0.);for(int layer=0;layer<2;layer++){for(int i=0;i<11;i++){float k=float(i),a=k*TAU/11.+tt*TAU,z=sin(a);if((z>=0.&&layer==0)||(z<0.&&layer==1))continue;float u=phase(g,k*.035,.61+k*.035);vec2 c=vec2(cos(a)*.39,.08+.49*z)*u;vec4 w=leafShape(p,c,dir2(a+.9),.084*u,.035*u,.68);w.rgb*=.76+.24*float(layer);v=over(v,w);}}return v;"
