    "body": "float grow=phase(q,.02,.46),hard=phase(q,.43,.72),e=p3Fade(q);vec4 v=vec4(0.);for(int layer=0;layer<2;layer++){for(int i=0;i<12;i++){float k=float(i),z=float(layer),u=phase(grow,k*.028,.60+k*.031),x=(k-5.5)*.127+.025*z;vec2 a=vec2(x,-.55-.09*z),b=a+vec2(.09*sin(k*2.7),(.23+.26*hash(vec2(k,7.)))*u);vec4 grass=leafShape(p,mix(a,b,.52),normalize(b-a+vec2(.001,.001)),length(b-a)*.55,.038*u,.7);grass.a*=1.-hard;v=over(v,grass);vec4 spike=p3Spike(p,a,a+(b-a)*(1.+.40*hard),(.043+.02*z)*u,k);spike.a*=hard;v=over(v,spike);}}v.a*=e;return v;",
