    "body": "vec2 a=vec2(-.72,.02),b=vec2(.61,.02);float g=phase(q,.00,.12),f=phase(q,.11,.57);vec2 c=mix(a,b,f);vec4 v=p3Seed(p,c,vec2(1.,.05),.091*g);v.a*=1.-smoothstep(.55,.61,q);float hit=phase(q,.57,1.);for(int i=0;i<22;i++){float k=float(i),ang=k*2.39996,rr=(.23+.47*hash(vec2(k,7.)))*growFast(hit);vec2 dir=dir2(ang),tip=b+dir*rr+vec2(0.,-.13*hit*hit);vec4 w=p3Spike(p,tip-dir*(.065+.045*hash(vec2(k,9.))),tip,.014,k);w.a*=sin(3.14159*hit);v=over(v,w);}return v;",
