    "loop": true,
    "note": "地表に白い菌糸の分岐網が張られ、交点を淡い感知光が伝播する持続素材。",
    "body": "float g=p3Growth(q),tt=p3Time(t,q);if(g<=.001)return vec4(0.);float z=0.,pulseV=0.;vec2 c=vec2(0.,-.30);for(int i=0;i<10;i++){float k=float(i),a=k*TAU/10.,u=phase(g,k*.024,.72+k*.024);vec2 dir=dir2(a)*vec2(1.,.34),m=c+dir*.31*u,b=c+dir*.76*u;z+=exp(-seg(p,c,m)/.005)*u+exp(-seg(p,m,b)/.0035)*u;for(int j=0;j<3;j++){float h=float(j),f=phase(u,.25+h*.16,.85+h*.05);vec2 x=mix(m,b,.20+h*.25),y=x+dir2(a+(h-1.)*.84+.36)*vec2(.20,.068)*f;z+=exp(-seg(p,x,y)/.003)*f;}float f=fract(tt+k*.13);pulseV+=ball(p,mix(c,b,f),.018)*sin(3.14159*f)*u;}return over(vec4(vec3(.78,.82,.65),sat(z*.91)),tone(pulseV*.43,vec3(.73,.95,.52)));",
