    "body": "float toxFormation=1.;float time=fract(t);vec4 v=vec4(0.);\nfor(int i=0;i<7;i++){float k=float(i),f=fract(time+hash(vec2(k,5.))),g=smoothstep(.03+k*.055,.35+k*.055,toxFormation);vec2 c=vec2((hash(vec2(k,9.))-.5)*.46+.065*sin(f*TAU+k),-.50+.95*f);vec4 w=toxCloud(p,c,vec2(.105,.16),time,k+41.,0.);w.a*=sin(3.14159*f)*g*.68;v=over(v,w);}\nvec4 bubbles=toxBubbles(p,vec2(0.,-.50),time,.54,1.02,13.,0.);bubbles.a*=smoothstep(.2,.75,toxFormation);return over(v,bubbles);"
