const forceImpactRevisionHelpers="\nvec4 fxWhite(float d,float w,float e){\n float core=exp(-abs(d)/max(.002,w)),halo=exp(-abs(d)/max(.006,w*4.));\n return vec4(mix(vec3(.69,.80,.98),vec3(1.),core),sat(e*(core*.9+halo*.28)));\n}\nvec4 fxPunch(vec2 p,vec2 c,float g,float e){\n vec2 z=(p-c)/max(.03,g);\n float d=seg(z,vec2(-.43,-.055),vec2(-.13,-.035))-.105;\n d=min(d,seg(z,vec2(-.19,-.04),vec2(.045,-.015))-.145);\n for(int i=0;i<4;i++){float k=float(i),y=-.115+.077*k;d=min(d,seg(z,vec2(.015,y),vec2(.15+.025*sin(k*1.2),y))-.053);}\n d=min(d,seg(z,vec2(-.12,.115),vec2(.065,.065))-.065);\n float fill=1.-smoothstep(-.022,.009,d);\n vec3 col=mix(vec3(.74,.84,.99),vec3(1.),smoothstep(.0,.10,-d));\n vec4 v=fxWhite(d,.018,e*.82);\n return over(v,vec4(col,fill*e*.96));\n}\nvec4 fxBurst(vec2 p,vec2 c,float f){\n if(f<=0.||f>=1.)return vec4(0.);\n float e=1.-smoothstep(.22,1.,f),g=1.-pow(1.-f,3.);\n vec4 v=fxWhite(length(p-c),.035+.07*g,e*exp(-f*5.)*1.3);\n for(int i=0;i<12;i++){float k=float(i),a=k*TAU/12.+.3*hash(vec2(k,13.));vec2 dir=dir2(a);float r=(.18+.29*hash(vec2(k,19.)))*g;\n v=over(v,fxWhite(seg(p,c+dir*r*.29,c+dir*r),.006+.009*(1.-f),e*(.65+.35*hash(vec2(k,23.)))));}\n return over(v,fxWhite(length(p-c)-(.05+.38*g),.012,e*.83));\n}\nvec2 fxCrackNode(float k,float ring0){\n float i=mod(k,9.);float a=i*TAU/9.+.17*(hash(vec2(i,17.))-.5);\n float r=ring0<1.5?mix(.18,.32,hash(vec2(i,31.))):mix(.45,.62,hash(vec2(i,41.)));\n return dir2(a+(ring0<1.5?.11*sin(i*2.3):0.))*r*vec2(1.,1.13);\n}\nfloat fxCross(vec2 a,vec2 b){return a.x*b.y-a.y*b.x;}\nvec4 fxPiece(vec2 p,vec2 root,vec2 a,vec2 b,vec2 c,float k,float f){\n vec2 center=(a+b+c)/3.;float angle=(hash(vec2(k,71.))-.5)*5.*f;\n vec2 ax=dir2(angle),ny=vec2(-ax.y,ax.x);\n vec2 dir=normalize(center+vec2(.001));\n vec2 offset=dir*(.08+.40*hash(vec2(k,63.)))*f+vec2(.07*f,-.15*f*f);\n vec2 z=p-root-center-offset;z=vec2(dot(z,ax),dot(z,ny));\n z.x/=max(.22,abs(cos(f*(1.4+2.6*hash(vec2(k,91.))))));z+=center;\n float sign0=sign(fxCross(b-a,c-a));\n float d=min(sign0*fxCross(b-a,z-a)/max(length(b-a),.001),min(sign0*fxCross(c-b,z-b)/max(length(c-b),.001),sign0*fxCross(a-c,z-c)/max(length(a-c),.001)));\n float e=1.-smoothstep(.35,1.,f);\n float fill=smoothstep(-.004,.004,d);\n float edge=min(seg(z,a,b),min(seg(z,b,c),seg(z,c,a)));\n vec3 col=mix(vec3(.40,.65,.98),vec3(.92,.97,1.),.5+.5*sin(k+f*7.));\n vec4 v=vec4(col,fill*e*.16);\n return over(v,ffGlow(edge,.004,e*.9,2.0));\n}\nvec4 fxFracture(vec2 p,vec2 root,float g,float e){\n vec4 v=vec4(0.);\n for(int i=0;i<9;i++){float k=float(i);vec2 a=fxCrackNode(k,1.),b=fxCrackNode(k+1.,1.),c=fxCrackNode(k,2.),d=fxCrackNode(k+1.,2.);\n float u=phase(g,0.,.52),h=phase(g,.40,1.);\n if(u>0.){v=over(v,ffGlow(seg(p,root,root+a*u),.005,e,1.8));}\n if(h>0.){v=over(v,ffGlow(seg(p,root+a,root+mix(a,c,h)),.004,e,1.8));v=over(v,ffGlow(seg(p,root+a,root+mix(a,b,h)),.004,e*.85,1.8));v=over(v,ffGlow(seg(p,root+a,root+mix(a,d,h)),.004,e*.72,1.8));}\n }return v;\n}\nvec4 fxShatter(vec2 p,vec2 root,float f){\n vec4 v=vec4(0.);\n for(int i=0;i<9;i++){float k=float(i);vec2 a=fxCrackNode(k,1.),b=fxCrackNode(k+1.,1.),c=fxCrackNode(k,2.),d=fxCrackNode(k+1.,2.);\n v=over(v,fxPiece(p,root,vec2(0.),a,b,k*3.,f));\n v=over(v,fxPiece(p,root,a,c,d,k*3.+1.,f));\n v=over(v,fxPiece(p,root,a,d,b,k*3.+2.,f));\n }return v;\n}\n";
const forcePowerHelpers="\nfloat fpEase(float x){return pow(sat(x),3.);}\nvec4 fpLight(float d,float w,float e,float power){\n float core=exp(-abs(d)/max(.002,w)),halo=exp(-abs(d)/max(.006,w*5.));\n return vec4(mix(vec3(.53,.72,1.),vec3(1.),core),sat(e*(core*.95+halo*.33*power)));\n}\nvec4 fpGather(vec2 p,vec2 c,float q,float end0,float r,float power){\n if(q<=0.||q>=end0)return vec4(0.);\n float f=phase(q,0.,end0),e=smoothstep(0.,.13,f)*(1.-smoothstep(.88,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<20;i++){float k=float(i),a=k*2.39996+f*1.8,rr=r*(.45+.55*hash(vec2(k,23.)))*(1.-.82*fpEase(f));vec2 dir=dir2(a),x=c+dir*rr;\n v=over(v,fpLight(seg(p,x,x+dir*(.05+.13*f)),.005+.003*f,e*.68,power));}\n return over(v,fpLight(length(p-c),.012+.045*f,e*.8,power));\n}\nvec4 fpImpact(vec2 p,vec2 c,float f,float r,float power){\n if(f<=0.||f>=1.)return vec4(0.);\n float g=1.-pow(1.-f,3.),e=1.-smoothstep(.12,1.,f);vec4 v=fpLight(length(p-c),.028+.045*g,e*exp(-f*7.)*1.45,power);\n for(int i=0;i<18;i++){float k=float(i),a=k*2.39996;vec2 d=dir2(a);float len=r*(.35+.65*hash(vec2(k,39.)))*g;\n v=over(v,fpLight(seg(p,c+d*len*.45,c+d*len),.008,e*.8,power));}\n return over(v,fpLight(length(p-c)-r*g,.016,e,power));\n}\nvec4 fpShield(vec2 p,float g,float t,float wobble){\n if(g<=.001)return vec4(0.);\n vec2 z=p-vec2(.36,0.);float y=z.y/max(g,.02);float x=.15-.20*y-.18*y*y+wobble;\n float thick=.045+.06*max(0.,1.-abs(y)/.76);\n float d=max(abs(y)-.76,abs(z.x-x)-thick);\n float mask=1.-smoothstep(-.009,.009,d);\n float scan=exp(-abs(y-.62*cos(t*TAU))/.09);\n vec4 v=vec4(.66,.82,1.,mask*(.065+.23*scan)*g);\n v=over(v,fpLight(d,.012,g,2.));\n return over(v,fpLight(z.x-x-thick,.006,mask*g*.8,1.8));\n}\nvec4 fpCage(vec2 p,float g,float t,float wobble){\n if(g<=.001)return vec4(0.);vec4 v=vec4(0.);float h=1.24*g,r=.67;vec2 base=vec2(0.,-.64);\n for(int i=0;i<6;i++){float k=float(i),a=k*TAU/6.;vec2 b=base+vec2(cos(a)*r,sin(a)*r*.34),top=b+vec2(wobble,h);\n float e=g*(.68+.32*step(0.,-sin(a)));v=over(v,fpLight(seg(p,b,top),.017,e,2.1));\n float f=.5+.5*cos(t*TAU+k);vec2 x=mix(b,top,f);v=over(v,fpLight(seg(p,x,x+vec2(0.,.10*g)),.011,e*.75,1.6));\n vec2 n=base+vec2(cos(a+TAU/6.)*r,sin(a+TAU/6.)*r*.34);\n v=over(v,fpLight(seg(p,b,n),.011,g*.9,1.9));v=over(v,fpLight(seg(p,top,n+vec2(wobble,h)),.013,g,2.1));}\n vec2 z=p-vec2(0.,-.64+h*.5);float m=(1.-smoothstep(.61,.67,abs(z.x)))*(1.-smoothstep(h*.48,h*.5+.002,abs(z.y)));\n return over(v,vec4(.68,.83,1.,m*g*.05));\n}\nvec4 fpPalm(vec2 p,vec2 c,float side,float close0,float g,float e){\n vec2 z=(p-c)*vec2(side,1.)/max(.02,g);\n float d=seg(z,vec2(-.40,-.36),vec2(-.16,-.14))-.17;\n d=min(d,seg(z,vec2(-.18,-.16),vec2(-.06,.10))-.19);\n for(int i=0;i<4;i++){float k=float(i),x=-.22+.104*k,y=.34+.15*sin((k+.4)*.73);vec2 a=vec2(x,.08),b=vec2(x+.05*close0,y-.09),cc=vec2(x+.16*close0,y-.12*close0);d=min(d,seg(z,a,b)-.061);d=min(d,seg(z,b,cc)-.054);}\n d=min(d,seg(z,vec2(.02,-.10),vec2(.24,.03+.12*close0))-.080);\n d=min(d,seg(z,vec2(.24,.03+.12*close0),vec2(.33,.15+.12*close0))-.063);\n float mask=1.-smoothstep(-.015,.009,d);vec3 col=mix(vec3(.64,.79,1.),vec3(1.),smoothstep(0.,.12,-d));\n vec4 v=fpLight(d,.022,e,3.);v=over(v,vec4(col,mask*e*.84));\n return v;\n}\n";
