const defenseTimingHelpers="\nvec4 dfLight(float d,float w,float e,float power){\n float a=exp(-abs(d)/max(.002,w)),b=exp(-abs(d)/max(.006,w*4.));\n return vec4(mix(vec3(.34,.68,1.),vec3(.98,1.,1.),a),sat(e*(.89*a+.24*b*power)));\n}\nfloat dfOpen(float f,float a,float b){float h=phase(f,a,b);return 1.-pow(1.-h,3.);}\nfloat dfShake(float f,float a,float b){float h=phase(f,a,b);return .032*sin(h*TAU*3.)*(1.-h)*step(a,f);}\nvec4 dfGather(vec2 p,vec2 c,float f,float power){\n if(f<=0.||f>=.39)return vec4(0.);\n float h=phase(f,0.,.34),e=smoothstep(0.,.09,f)*(1.-smoothstep(.30,.39,f));vec4 v=vec4(0.);\n for(int i=0;i<15;i++){float k=float(i),a=k*2.39996+h*1.7;vec2 d=dir2(a);float r=(.22+.37*hash(vec2(k,13.)))*(1.-h*h);vec2 x=c+d*r;v=over(v,dfLight(seg(p,x,x+d*.055),.006,e*.65,power));}\n return over(v,dfLight(length(p-c),.023,e,power));\n}\nvec4 dfFlash(vec2 p,vec2 c,float f,float power){\n float e=gate(f,.36,.65);return dfLight(length(p-c),.045,e,power);\n}\nvec4 dfShield(vec2 p,vec2 c,float g,float t,float w,float power,float hard){\n if(g<=.001)return vec4(0.);\n vec2 z=p-c;float y=z.y/max(.02,g);float h=abs(y)/.65;\n float x=hard>.5?.10-.16*max(0.,h-.46)/.54:.11-.14*h*h;\n x-=.08*y;\n float thick=mix(.028,.078,hard)*(1.-.35*sat(h));\n float d=max(abs(y)-.65,abs(z.x-x)-thick);\n float mask=1.-smoothstep(-.006,.007,d);float scan=exp(-abs(y-.54*cos(TAU*t))/.11);\n vec4 v=vec4(.43,.76,1.,mask*g*(.055+.10*scan+.06*hard));\n v=over(v,dfLight(d,w,g,power));\n if(hard>.5){\n float d2=max(abs(y)-.53,abs(z.x-x+.018)-thick*.45);\n v=over(v,dfLight(d2,.006,g*.72,power));\n }\n return v;\n}\nvec4 dfFloor(vec2 p,float g,float t,float e){\n if(g<=.001)return vec4(0.);\n vec2 z=(p-vec2(0.,-.59))/vec2(max(.02,.72*g),max(.007,.245*g));\n float r=length(z),a=atan(z.y,z.x);\n vec4 v=vec4(.49,.78,1.,(1.-smoothstep(.92,1.,r))*e*.045);\n v=over(v,dfLight((r-1.)*.245*g,.008,e,1.));\n v=over(v,dfLight((r-.76)*.245*g,.005,e*.75,1.));\n float marks=exp(-abs(sin(a*8.))/.20)*exp(-abs(r-.88)/.045);\n v=over(v,vec4(.85,.95,1.,marks*e*.75));\n for(int i=0;i<10;i++){float k=float(i),f=fract(t+hash(vec2(k,8.))),a0=k*TAU/10.;vec2 c=vec2(.61*g*cos(a0),-.59+.18*g*sin(a0)+.88*f*g);\n v=over(v,dfLight(length(p-c),.009,e*sin(3.14159*f)*.72,1.));}\n return v;\n}\nvec4 dfBubble(vec2 p,vec2 r,float t,float g,float power,float life){\n if(g<=.001)return vec4(0.);\n vec2 z=p/max(r*g,vec2(.012));float l=length(z),a=atan(z.y,z.x),d=(l-1.)*min(r.x,r.y)*g;\n float mask=1.-smoothstep(.94,1.,l);\n float tint=.028+.030*life;\n vec4 v=vec4(.47,.79,1.,mask*tint*g);\n v=over(v,dfLight(d,.008+.004*life,g,power));\n float shine=pow(max(0.,cos(a-2.15)),13.)*exp(-abs(l-.91)/.038);\n v=over(v,vec4(.93,.99,1.,shine*g*(.63+.25*life)));\n float glint=pow(max(0.,cos(a+.7+t*TAU)),19.)*exp(-abs(l-.96)/.025);\n v=over(v,vec4(.75,.93,1.,glint*g*.55));\n if(life>.5){for(int i=0;i<15;i++){float k=float(i),f=fract(t+hash(vec2(k,18.)));vec2 c=dir2(k*2.39996)*r*g*(.72+.22*hash(vec2(k,27.)));c.y+=.08*(f-.5);v=over(v,dfLight(length(p-c),.009,g*sin(3.14159*f)*.62,power));}}\n return v;\n}\nvec4 dfHex(vec2 p,vec2 c,vec2 r,float g,float e,float t){\n if(g<=.001)return vec4(0.);\n vec2 z=(p-c)/max(r*g,vec2(.007));float d=fPoly(z,6.,TAU/12.)-.86;\n float mask=1.-smoothstep(-.04,.015,d);float pulse=.5+.5*cos(t*TAU);\n vec4 v=vec4(.36,.68,1.,mask*e*g*(.045+.045*pulse));\n return over(v,dfLight(d*min(r.x,r.y)*g,.006,e*g,2.1));\n}\n";
const gravityIndividual={"337":["弱い重力歪み。対象近傍を通る光が細く屈曲して視認方向の変化を表現。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=smoothstep(.04,.70,f);return gvLens(p,ft,g*.70,.7);"],"338":["軽量化。細い紫白の光粒子が軽く上昇する。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=smoothstep(.04,.62,f);vec4 v=vec4(0.);for(int i=0;i<10;i++){float k=float(i),h=fract(ft+hash(vec2(k,31.))),x=(hash(vec2(k,14.))-.5)*.85;vec2 c=vec2(x+.035*sin(h*TAU+k),-.64+1.22*h);v=over(v,gvLight(seg(p,c,c-vec2(0.,.065)),.006,g*sin(3.14159*h)*.75,.8));}return v;"],"339":["水平1:.34の透明な重力圧力面が真下に急降下し、足元で小衝撃。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvGather(p,vec2(0.,.60),q,.24,.35,.9);for(int i=0;i<2;i++){float k=float(i),a=.24+.075*k,b=a+.30,f=phase(q,a,b);if(q>=a&&q<b+.075){float e=smoothstep(a,a+.045,q)*(1.-smoothstep(b,b+.075,q));v=over(v,gvPressureDrop(p,f,e*(1.-.28*k),.43,.95));}}return over(v,gvGround(p,vec2(0.,-.61),phase(q,.54,1.),.48,.9));"],"340":["周囲の光と小さな岩片を中心に引き寄せる短い吸引。","if(q<=0.||q>=1.)return vec4(0.);float g=phase(q,.09,.75),e=smoothstep(.02,.13,q)*(1.-smoothstep(.76,1.,q));vec4 v=vec4(0.);for(int i=0;i<18;i++){float k=float(i),a=k*2.39996+.7*g;vec2 d=dir2(a);float r=(.35+.58*hash(vec2(k,13.)))*(1.-g*g);vec2 c=d*r;v=over(v,gvLight(seg(p,c,c+d*.13),.008,e,1.));if(i<9)v=over(v,gvRock(p,c,.027,k+g*3.,e));}return over(v,gvLight(length(p),.034,gate(q,.67,1.),1.));"],"341":["無重力。足元から小石が持ち上がり、上下にゆっくり漂う。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=gvFast(phase(f,.06,.62));vec4 v=vec4(0.);for(int i=0;i<12;i++){float k=float(i),x=(hash(vec2(k,33.))-.5)*1.3,y=-.55+g*(.24+hash(vec2(k,43.))*.99+.06*sin(ft*TAU+k));vec2 c=vec2(x+.05*g*sin(ft*TAU+k),y);v=over(v,gvRock(p,c,.021+.021*hash(vec2(k,15.)),k+.35*sin(ft*TAU),g));v=over(v,gvLight(seg(p,c,c-vec2(0.,.08)),.004,g*.40,1.));}return v;"],"342":["超重力。水平1:.34の重力圧力面を3層連続で真下へ加速させ、接地亀裂と岩片。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvGather(p,vec2(0.,.58),q,.25,.54,1.5);for(int i=0;i<3;i++){float k=float(i),a=.28+k*.105,b=a+.27,f=phase(q,a,b);if(q>=a&&q<b+.065){float e=smoothstep(a,a+.045,q)*(1.-smoothstep(b,b+.065,q));v=over(v,gvPressureDrop(p,f,e,.61+.035*k,1.4));}v=over(v,gvGround(p,vec2(0.,-.61),phase(q,b,min(1.,b+.29)),.67,1.5));}return over(v,gvCracks(p,vec2(0.,-.61),phase(q,.55,.82),gate(q,.55,1.),1.3));"],"343":["広い水平1:.34の圧力面が繰り返し真下へ降下する重力場。形成後は下降周期を維持。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=gvFast(phase(f,.39,.67));vec4 v=gvGather(p,vec2(0.,.53),f,.34,.70,1.9);if(g<=.001)return v;for(int i=0;i<4;i++){float k=float(i),h=fract(ft+k*.25);float e=g*smoothstep(0.,.12,h)*(1.-smoothstep(.84,1.,h));v=over(v,gvPressureDrop(p,h,e*.82,.80,1.9));}for(int i=0;i<8;i++){float k=float(i),h=fract(ft+hash(vec2(k,19.))),x=(hash(vec2(k,41.))-.5)*1.4;vec2 c=vec2(x,.74-1.30*h*h);v=over(v,gvRock(p,c,.020,k+h,g*sin(3.14159*h)*.58));}return over(v,gvPressurePlane(p,-.61,.82,g*.34,1.6));"],"344":["斥力。圧縮したエネルギーを一瞬止め、全方位へ急放出。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvGather(p,vec2(0.),q,.37,.70,1.9);v=over(v,gvLight(length(p),.042,gate(q,.27,.46),2.));for(int i=0;i<3;i++){float k=float(i);v=over(v,gvWave(p,vec2(0.),phase(q,.43+.07*k,.82+.07*k),.91,1.9,1.));}return over(v,gvGround(p,vec2(0.,-.53),phase(q,.46,1.),.81,1.7));"],"345":["圧壊球。対象に暗い高密度球を形成し、粒子と岩片を巻き込み急収縮。","if(q<=0.||q>=1.)return vec4(0.);float g=gvFast(phase(q,.10,.36)),h=pow(phase(q,.53,.76),2.5),e=g*(1.-smoothstep(.77,.94,q));vec4 v=gvGather(p,vec2(0.),q,.36,.68,2.);for(int i=0;i<16;i++){float k=float(i),a=k*2.39996+q*TAU*2.;vec2 d=dir2(a);float r=(.32+.54*hash(vec2(k,13.)))*(1.-h);vec2 c=d*r;v=over(v,gvRock(p,c,.021,k+q*7.,e*.85));v=over(v,gvLight(seg(p,c,c+dir2(a-.28)*.10),.006,e,2.));}v=over(v,gvOrb(p,vec2(0.),max(.012,.39*g*(1.-h)),e,q,2.));return over(v,gvLight(length(p),.047,gate(q,.75,.96),2.3));"],"346":["潮汐力。上下で異なる引力を作用させ、光の筋を強く引き伸ばす。","if(q<=0.||q>=1.)return vec4(0.);return gvTide(p,q,2.3,0.);"],"347":["重力落下。上空に巨大な水平1:.34の重力圧力面が形成・静止し、3層が高速で真下へ落下。接地を砕く。","if(q<=0.||q>=1.)return vec4(0.);vec2 start=vec2(0.,.64),end0=vec2(0.,-.61);float g=gvFast(phase(q,.05,.34));vec4 v=gvGather(p,start,q,.33,.64,2.4);for(int i=0;i<3;i++){float k=float(i),a=.43+k*.045,b=a+.19,f=phase(q,a,b),travel=pow(f,2.6);float e=g*smoothstep(.10+.055*k,.30+.025*k,q)*(1.-smoothstep(b,b+.065,q));float y=mix(.64+.085*k,-.61,travel);float r=(.80-.045*k)*g;v=over(v,gvPressurePlane(p,y+.10*(1.-f),r,e*.22,2.4));v=over(v,gvPressurePlane(p,y,r,e,2.4));v=over(v,gvGround(p,end0,phase(q,b,1.),.94,2.5));}v=over(v,gvCracks(p,end0,phase(q,.62,.87),gate(q,.62,1.),2.5));return v;"],"348":["放免。束縛された光の筋がほどけ、粒子が外側へゆっくり解放される。","if(q<=0.||q>=1.)return vec4(0.);float g=phase(q,.06,.32),h=gvFast(phase(q,.43,.87)),e=smoothstep(.03,.17,q)*(1.-smoothstep(.75,1.,q));vec4 v=vec4(0.);for(int i=0;i<18;i++){float k=float(i),a=k*2.39996+h*.6;vec2 d=dir2(a);float r=.18+.69*h;vec2 c=d*r;v=over(v,gvLight(seg(p,c,c-d*(.14*(1.-h)+.025)),.007,e*g,2.1));}return over(v,gvLight(length(p),.034,gate(q,.35,.55),2.));"],"349":["重力レンズ。光が対象周囲へ大きく曲がり込む。形成時の収束と振動から安定した光路へ。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=gvFast(phase(f,.39,.70)),w=.018*sin(phase(f,.70,.95)*TAU*3.)*(1.-phase(f,.70,.95));vec4 v=gvGather(p,vec2(0.),f,.35,.78,2.7);return over(v,gvLens(p+vec2(w,0.),ft,g,3.));"],"350":["重力波。溜めと止めから大規模な時空の変動を連続伝播。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvGather(p,vec2(0.),q,.37,.85,2.7);v=over(v,gvLight(length(p),.051,gate(q,.28,.46),2.8));for(int i=0;i<5;i++){float k=float(i),f=phase(q,.43+.065*k,.74+.065*k);v=over(v,gvWave(p,vec2(0.),f,.98,2.7,.74));if(f>0.&&f<1.)v=over(v,gvLens(p,q,gate(f,0.,1.)*.32,2.3));}return v;"],"351":["潮汐破砕。強い上下の重力差で伸長し、停止後に破砕片が異なる方向へ引き離される。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvTide(p,q,2.9,1.);float f=phase(q,.69,1.);if(f>0.){for(int i=0;i<22;i++){float k=float(i),a=k*2.39996;vec2 d=dir2(a);vec2 c=d*vec2(.21+.37*f,.22+.83*gvFast(f));v=over(v,gvRock(p,c,.023+.022*hash(vec2(k,24.)),k+f*6.,1.-f));}v=over(v,gvLight(length(p),.055,gate(q,.69,.85),2.9));}return v;"],"352":["排斥。高密度に蓄えた重力を急解放し、大きな波と岩片を全方向へ押し出す。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=gvGather(p,vec2(0.),q,.40,.87,2.9);v=over(v,gvLight(length(p),.063,gate(q,.31,.47),3.));for(int i=0;i<5;i++){float k=float(i);v=over(v,gvWave(p,vec2(0.),phase(q,.45+.05*k,.77+.055*k),1.10,3.,1.));}float f=phase(q,.45,1.);if(f>0.){for(int i=0;i<25;i++){float k=float(i),a=k*2.39996;vec2 d=dir2(a),c=d*(.12+.95*gvFast(f))*(.55+.45*hash(vec2(k,13.)));v=over(v,gvRock(p,c,.024+.025*hash(vec2(k,31.)),k+f*7.,1.-f));v=over(v,gvLight(seg(p,c,c-d*.15*(1.-f)),.008,1.-f,2.7));}}return v;"],"353":["黒穴。暗い中心と横視点の強発光降着流を形成し、岩片と光を巻き込む。終盤に極限収束・消滅。","if(q<=0.||q>=1.)return vec4(0.);float g=gvFast(phase(q,.06,.38)),h=pow(phase(q,.76,.93),3.),e=g*(1.-smoothstep(.93,1.,q));float r=max(.009,.24*g*(1.-h));vec4 v=gvGather(p,vec2(0.),q,.35,.95,3.1);vec2 z=p/vec2(1.,.34);float rr=length(z),a=atan(z.y,z.x);float n=fb(z*4.+vec2(q*3.,q));float swirl=5.*(a+rr*3.8)-q*TAU*15.+n;float arm=pow(.5+.5*cos(swirl),3.);float env=smoothstep(r*.85,r*1.5,rr)*(1.-smoothstep(.78,.99,rr))*e;v=over(v,vec4(mix(vec3(.44,.19,.91),vec3(1.,.94,1.),arm),sat(env*(.20+.67*arm))));for(int i=0;i<28;i++){float k=float(i),f=fract(q*3.3+hash(vec2(k,17.))),rad=mix(.97,r,f)*(1.-.85*h),ang=k*2.39996+q*TAU*3.+3.*f;vec2 c=dir2(ang)*rad*vec2(1.,.52);float en=e*sin(3.14159*f);v=over(v,gvRock(p,c,.022+.022*hash(vec2(k,15.)),k+q*9.,en));v=over(v,gvLight(seg(p,c,c+dir2(ang-.5)*.13),.006,en,3.));}v=over(v,gvOrb(p,vec2(0.),r,e,q,3.));return over(v,gvLight(length(p),.037,gate(q,.90,1.)*.80,3.));"]};
const gravityIndividualHelpers="\nvec4 gvLight(float d,float w,float e,float power){\n float a=exp(-abs(d)/max(.002,w)),b=exp(-abs(d)/max(.006,w*4.5));\n return vec4(mix(vec3(.38,.19,.72),vec3(.91,.89,1.),a),sat(e*(a*.92+b*.27*power)));\n}\nfloat gvFast(float f){return 1.-pow(1.-sat(f),3.);}\nvec4 gvRock(vec2 p,vec2 c,float r,float a,float e){\n vec2 z=(p-c)/max(.004,r);vec2 ax=dir2(a);z=vec2(dot(z,ax),dot(z,vec2(-ax.y,ax.x)));\n float d=max(abs(z.x)+.34*z.y,abs(z.y)*1.22+.26*z.x)-.85;\n vec4 v=vec4(mix(vec3(.09,.065,.16),vec3(.38,.29,.52),sat(.5+z.y*.3-z.x*.2)),(1.-smoothstep(-.04,.07,d))*e);\n return over(v,gvLight(d*r,.004,e*.70,1.2));\n}\nvec4 gvGather(vec2 p,vec2 c,float q,float end0,float r,float power){\n if(q<=0.||q>=end0)return vec4(0.);\n float f=phase(q,0.,end0),e=smoothstep(0.,.13,f)*(1.-smoothstep(.83,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<20;i++){float k=float(i),a=k*2.39996+f*1.3;vec2 d=dir2(a);float rr=r*(.48+.52*hash(vec2(k,27.)))*(1.-f*f);vec2 x=c+d*rr;v=over(v,gvLight(seg(p,x,x+d*(.045+.09*f)),.007,e*.70,power));}\n return over(v,gvLight(length(p-c),.025+.02*f,e,power));\n}\nvec4 gvGround(vec2 p,vec2 c,float f,float r,float power){\n if(f<=0.||f>=1.)return vec4(0.);float g=gvFast(f),e=1.-smoothstep(.12,1.,f);vec4 v=gvLight((length((p-c)/vec2(1.,.34))-r*g)*.34,.014,e,power);\n for(int i=0;i<14;i++){float k=float(i),a=k*2.39996;vec2 d=dir2(a);vec2 x=c+vec2(d.x*r*g,.20*d.y*g+(.16+.20*hash(vec2(k,31.)))*sin(3.14159*f));v=over(v,gvRock(p,x,.022+.017*hash(vec2(k,52.)),k+f*4.,e));}\n return over(v,gvLight(length(p-c),.045,e*exp(-f*8.),power));\n}\nvec4 gvCracks(vec2 p,vec2 c,float g,float e,float power){\n vec4 v=vec4(0.);\n for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.+.35*(hash(vec2(k,26.))-.5);vec2 d=dir2(a),n=vec2(-d.y,d.x),prev=c;\n for(int j=1;j<=4;j++){float h=float(j),r=h/4.;vec2 x=c+d*.78*r*vec2(1.,.34)+n*.10*(hash(vec2(k,h))-.5)*r;float f=phase(g,(h-1.)/4.,r);if(f>0.)v=over(v,gvLight(seg(p,prev,mix(prev,x,f)),.006,e,power));prev=x;}}\n return v;\n}\nvec4 gvDown(vec2 p,float f,float e,float power,float width0){\n vec4 v=vec4(0.);float head=mix(.92,-.61,gvFast(f));float tail=head+.51;\n for(int i=0;i<11;i++){float k=float(i),x=(k-5.)*width0/5.;float h=.10*(hash(vec2(k,13.))-.5);v=over(v,gvLight(seg(p,vec2(x,head+h),vec2(x*.88,tail+h)),.008+.009*power,e*(.60+.4*hash(vec2(k,41.))),power));}\n return v;\n}\nvec4 gvWave(vec2 p,vec2 c,float f,float radius,float power,float squash){\n if(f<=0.||f>=1.)return vec4(0.);\n float r=.025+radius*gvFast(f),e=1.-smoothstep(.18,1.,f);vec2 z=(p-c)/vec2(1.,squash);float a=atan(z.y,z.x);float d=(length(z)-r-.025*sin(a*9.+f*10.))*min(1.,squash);\n return gvLight(d,.013+.006*power,e,power);\n}\nvec4 gvTide(vec2 p,float q,float power,float damage){\n float build=phase(q,.03,.35),h=phase(q,.43,.70),e=smoothstep(.04,.14,q)*(1.-smoothstep(.80,1.,q));float w=.012*sin(q*TAU*25.)*gate(q,.22,.41);vec4 v=gvGather(p,vec2(0.),q,.33,.55,power);\n for(int i=0;i<18;i++){float k=float(i),s0=step(8.5,k)*2.-1.;float x=(hash(vec2(k,13.))-.5)*.75;float y=s0*(.09+.70*h*h+hash(vec2(k,81.))*.13);vec2 tip=vec2(x*(1.-.55*h)+w,y),tail=vec2(x*.65,s0*max(.015,abs(y)-(.12+.30*h)));\n v=over(v,gvLight(seg(p,tail,tip),.007+.004*power,e*build,power));if(damage>.5&&h>.4){vec2 c=tip+vec2(.10*sin(k),s0*.14*h);v=over(v,gvRock(p,c,.025+.017*hash(vec2(k,12.)),k+q*8.,e*h));}}\n return v;\n}\nvec4 gvLens(vec2 p,float t,float g,float power){\n if(g<=.001)return vec4(0.);\n vec4 v=vec4(0.);float mask=1.-smoothstep(.63,.95,abs(p.x));float sway=.025*sin(t*TAU);\n for(int i=0;i<9;i++){float k=float(i),y=(k-4.)*.16;float deflect=sign(y+.001)*(.15+.04*power)*exp(-p.x*p.x*7.)*exp(-abs(y)*1.6);float yy=y+deflect*g+sway*sin(p.x*6.+k);float d=abs(p.y-yy);v=over(v,gvLight(d,.004+.002*power,mask*g*(.45+.25*cos(t*TAU+k)),power));}\n return v;\n}\nvec4 gvOrb(vec2 p,vec2 c,float r,float e,float t,float power){\n if(r<=.003||e<=.001)return vec4(0.);\n vec2 z=(p-c)/r;float d=length(z),a=atan(z.y,z.x);float n=fb(z*3.+dir2(t*TAU)*.25);\n float rim=d-1.+.045*sin(a*8.+t*TAU*2.);\n vec4 v=vec4(mix(vec3(.022,.012,.055),vec3(.23,.09,.44),n*n),(1.-smoothstep(.91,1.03,d))*e*.96);\n v=over(v,gvLight(rim*r,.010*power,e,power));return v;\n}\n";
for(const r of records){if(gravityIndividual[r.row]){r.note="個別改修版："+gravityIndividual[r.row][0]+(rows[r.id]&&!rows[r.id].description?" 効果説明未記入のため名称に基づく暫定演出。":"");r.refined=true;}}
const darkIndividual={"386":["低い黒い煙が対象周囲へ広がり視界を覆う。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.06,.65));vec4 v=vec4(0.);for(int i=0;i<5;i++){float k=float(i);vec2 c=vec2((k-2.)*.19,.08*sin(ft*TAU+k));v=over(v,dkCloud(p,c*g,vec2(.33,.43)*g,ft+k*.15,g*.73,.65,dkPurple()));}return v;"],"387":["足元の影が立ち上がり身体の外側を薄く覆う。隠密の膜。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.08,.63));return dkVeil(p,ft,g,0.);"],"388":["右前方へ黒い幕が上から降り、布状の折り目が揺れる。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;return dkCurtain(p,ft,dkFast(phase(f,.07,.70)),0.);"],"389":["左から右へ鋭い闇の貫通線。暗い芯と紫白の縁。","if(q<=0.||q>=1.)return vec4(0.);float g=dkFast(phase(q,.12,.32)),h=dkFast(phase(q,.36,.66));vec2 a=mix(vec2(-.87,0.),vec2(.91,0.),h),b=mix(vec2(-.87,0.),vec2(.91,0.),g);vec4 v=vec4(0.);if(g>h){float d=seg(p,a,b),e=gate(q,.09,.71);v=dkLight(abs(d-.025),.009,e,1.4,dkPurple());v=over(v,vec4(.019,.004,.044,(1.-smoothstep(.013,.023,d))*e));}return over(v,dkCloud(p,vec2(.80,0.),vec2(.13),t,gate(q,.31,.80),.7,dkPurple()));"],"390":["重い濃密な闇と緩やかな下向きの流れ。睡眠を示す静かな動き。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.07,.71));vec4 v=vec4(0.);for(int i=0;i<7;i++){float k=float(i);vec2 c=vec2(.32*cos(k*2.39996),.22*sin(k*2.39996)-.10*sin(ft*TAU+k))*g;v=over(v,dkCloud(p,c,vec2(.37,.47)*g,ft+k*.1,g*.78,1.,dkPurple()));}return v;"],"391":["周辺光が順に消え、柔らかい暗所へ変わる。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.08,.70));float r=length(p/vec2(.87,.80));vec4 v=vec4(.016,.008,.035,(1.-smoothstep(.35,.99,r))*g*.76);for(int i=0;i<12;i++){float k=float(i),a=k*2.39996;vec2 c=dir2(a)*(.55+.15*sin(k));float e=(1.-g)*smoothstep(0.,.15,f);v=over(v,dkLight(length(p-c),.012,e,.8,vec3(.73,.67,.91)));}return v;"],"392":["虚無の渦。黒紫の流れが対象中心へ巻き込まれ短く消滅。","if(q<=0.||q>=1.)return vec4(0.);float g=dkFast(phase(q,.05,.31)),h=phase(q,.67,.96),e=g*(1.-smoothstep(.78,1.,q));return dkVortex(p,q,max(.009,.18*g*(1.-h)),e,1.5);"],"393":["影が右側へ伸びて立ち上がる分身出現用の闇。実際の分身画像はゲーム側。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.08,.51)),h=dkFast(phase(f,.32,.77));vec4 v=dkCloud(p,vec2(.26*g,-.61),vec2(.45*g,.12*g),ft,g,.9,dkPurple());v=over(v,dkCloud(p,vec2(.43,-.61+.56*h),vec2(.27,.60*h),ft,h*.70,.65,dkPurple()));return v;"],"394":["溜めから右前方の強い遮光面を急展開。指定方向の遮光。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.39,.67));vec4 v=dkGather(p,vec2(.42,0.),f,.34,.64,1.8,dkPurple());return over(v,dkCurtain(p,ft,g,1.));"],"395":["濃い闇が急拡大し、青白い冷気と霜粒を伴う。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.37,.66));vec4 v=dkGather(p,vec2(0.),f,.33,.72,1.9,dkPurple());for(int i=0;i<7;i++){float k=float(i);vec2 c=dir2(k*2.39996)*.36*g;v=over(v,dkCloud(p,c,vec2(.45,.53)*g,ft+k*.15,g*.83,1.,vec3(.15,.24,.42)));}for(int i=0;i<16;i++){float k=float(i),h=fract(ft+hash(vec2(k,31.)));vec2 c=vec2((hash(vec2(k,7.))-.5)*1.6,.67-1.34*h)*g;v=over(v,dkLight(length(p-c),.006,g*sin(3.14159*h)*.60,1.2,vec3(.51,.73,1.)));}return v;"],"396":["夜の衣。黒い布のようなエネルギーが蓄積後に身体を包み、流れる。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.36,.68));vec4 v=dkGather(p,vec2(0.,-.4),f,.32,.64,1.9,dkPurple());return over(v,dkVeil(p,ft,g,1.));"],"397":["光を覆う食。暗い影が急速に広がり、光源を隠す。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.40,.72));vec4 v=dkGather(p,vec2(0.),f,.34,.75,2.2,dkPurple());return over(v,dkEclipse(p,ft,g,2.2));"],"398":["暗黒星雲。横長に広がる黒紫の塵・星雲の靄と濃淡のある暗黒帯。大小78個の青白・淡紫の星粒が奥行きを持って散在し、静かに瞬く。発動は収束後に急展開、持続は緩やかな流動。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.38,.76));vec4 v=dkGather(p,vec2(0.),f,.34,.84,2.2,dkPurple());return over(v,dkNebula398(p,ft,g));"],"399":["闇の蓄積と止めから、地面を這う闇の奔流が全方向へ炸裂。","if(q<=0.||q>=1.)return vec4(0.);vec4 v=dkGather(p,vec2(0.,-.40),q,.36,.76,2.3,dkPurple());float f=dkFast(phase(q,.43,.80)),e=gate(q,.42,1.);for(int i=0;i<12;i++){float k=float(i),a=k*TAU/12.;vec2 c=vec2(0.,-.48)+dir2(a)*vec2(.91,.31)*f;v=over(v,dkCloud(p,c,vec2(.14+.19*f,.12+.12*f),t+k*.14,e,.94,dkPurple()));}return over(v,dkLight(length(p-vec2(0.,-.42)),.045,gate(q,.42,.62),2.4,dkPurple()));"],"400":["周囲の光を選択的に集め、闇へ吸収する。岩片なし。","if(q<=0.||q>=1.)return vec4(0.);return dkAbsorb(p,q,2.6,0.);"],"401":["神聖な闇。金白の光が集まり、静穏な黒い領域へ展開。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.40,.74));vec4 v=dkGather(p,vec2(0.),f,.35,.73,2.4,dkGold());return over(v,dkQuiet(p,ft,g,0.));"],"402":["虚無球。闇と呪いの黒紫球が対象を侵食し、歪んだ稲妻を放つ。","if(q<=0.||q>=1.)return vec4(0.);float g=dkFast(phase(q,.08,.39)),e=g*(1.-smoothstep(.80,1.,q));vec4 v=dkGather(p,vec2(0.),q,.36,.75,2.6,dkPurple());v=over(v,dkOrb(p,vec2(0.),.38*g,e,q,2.7));float h=phase(q,.45,.82);for(int i=0;i<9;i++){float k=float(i),a=k*TAU/9.+.12*sin(q*TAU*18.+k);vec2 d=dir2(a),n=vec2(-d.y,d.x),x=d*.36*g,y=d*(.46+.13*h)+n*.07*sin(k+q*TAU*15.),z=d*(.54+.30*h)-n*.05;float en=gate(q,.45,.96);v=over(v,dkLight(min(seg(p,x,y),seg(p,y,z)),.007,en,2.6,dkPurple()));}return v;"],"403":["安息の闇。広い暗黒領域を荘厳に展開し、金白の微光とともに静止・隔絶。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;float g=dkFast(phase(f,.41,.76));vec4 v=dkGather(p,vec2(0.),f,.36,.93,3.,dkGold());return over(v,dkQuiet(p,ft,g,1.));"],"404":["常闇の檻。暗黒の柱が時間差で立ち上がり、闇の壁で閉じ込める。","float fieldForm=1.;float ft=fract(t);float f=fieldForm;vec4 v=dkGather(p,vec2(0.,-.49),f,.34,.88,3.,dkPurple());for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.;float g=dkFast(phase(f,.37+.028*k,.61+.028*k));if(g<=.001)continue;vec2 c=vec2(.72*cos(a),-.58+.18*sin(a));vec2 x=c+vec2(0.,1.26*g);float d=seg(p,c,x);vec4 w=vec4(.018,.006,.044,(1.-smoothstep(.047,.074,d))*g);w=over(w,dkLight(abs(d-.060),.008,g*.75,2.9,dkPurple()));v=over(v,w);}float g=dkFast(phase(f,.62,.88));vec2 z=p/vec2(.73,.70);float edge=abs(length(z)-1.);v=over(v,vec4(.025,.008,.058,(1.-smoothstep(.03,.16,edge))*g*.68));return v;"],"405":["常闇の吸引。光と黒い奔流を大量に巻き込み極限収束。岩片なし、黒穴との差別化。","if(q<=0.||q>=1.)return vec4(0.);return dkAbsorb(p,q,3.1,1.);"]};
const darkIndividualHelpers="\nfloat dkFast(float f){return 1.-pow(1.-sat(f),3.);}\nvec4 dkLight(float d,float w,float e,float power,vec3 hue){\n float a=exp(-abs(d)/max(.002,w)),b=exp(-abs(d)/max(.006,w*4.5));\n return vec4(mix(hue,vec3(.96,.91,1.),a),sat(e*(.88*a+.24*b*power)));\n}\nvec3 dkPurple(){return vec3(.39,.16,.74);}\nvec3 dkGold(){return vec3(.81,.65,.37);}\nvec4 dkCloud(vec2 p,vec2 c,vec2 r,float t,float e,float dense,vec3 hue){\n if(e<=.001)return vec4(0.);\n vec2 z=(p-c)/max(r,vec2(.012)),a=dir2(t*TAU);float n=fb(z*3.7+a*.55),m=fb(z*7.9-a*.36);\n float d=length(z)+.46*(n-.5)+.18*(m-.5);\n float mask=1.-smoothstep(.52,1.08,d);\n float alpha=sat(mask*e*(.38+.45*dense+.18*n));\n vec3 col=mix(vec3(.017,.009,.036),hue,.12+.19*n+.10*m);\n return vec4(col,alpha);\n}\nvec4 dkGather(vec2 p,vec2 c,float q,float end0,float r,float power,vec3 hue){\n if(q<=0.||q>=end0)return vec4(0.);\n float f=phase(q,0.,end0),e=smoothstep(0.,.10,f)*(1.-smoothstep(.82,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<22;i++){float k=float(i),a=k*2.39996+f*2.;vec2 d=dir2(a);float rr=r*(.38+.62*hash(vec2(k,17.)))*(1.-f*f);vec2 x=c+d*rr;v=over(v,dkLight(seg(p,x,x+d*(.05+.09*f)),.007,e*.65,power,hue));}\n return over(v,dkCloud(p,c,vec2(.06+.17*f),q,e,1.,hue));\n}\nvec4 dkVeil(vec2 p,float t,float g,float strong){\n if(g<=.001)return vec4(0.);vec4 v=vec4(0.);\n for(int i=0;i<5;i++){float k=float(i),x=(k-2.)*.15;float y=-.61+.54*g;vec2 c=vec2(x+.06*sin(t*TAU+k),y);\n vec2 z=p-c;z.x-=.10*sin(z.y*8.+t*TAU+k)*g;\n vec4 w=dkCloud(z,vec2(0.),vec2(.20+.045*strong,.63*g),t+k*.12,g*(.44+.12*strong),.65,dkPurple());\n v=over(v,w);}\n float a=atan(p.y+.55,p.x);float d=(length((p-vec2(0.,-.58))/vec2(1.,.34))-.59*g)*.34;\n return over(v,dkLight(d,.007,g*.34,1.+strong,dkPurple()));\n}\nvec4 dkCurtain(vec2 p,float t,float g,float hard){\n if(g<=.001)return vec4(0.);vec2 c=vec2(.43,.70-.70*g),z=p-c;\n float y=z.y/max(.015,.76*g),fold=.08*sin(y*8.+t*TAU)+.045*sin(y*17.-t*TAU);\n float x=z.x-fold;float w=.12+.08*hard+.05*sin(y*7.);\n float d=max(abs(y)-1.,(abs(x)-w)/.22);\n float mask=1.-smoothstep(-.08,.06,d);\n vec4 v=vec4(mix(vec3(.015,.008,.027),vec3(.22,.10,.37),.3+.3*cos(x*31.+y*4.)),mask*g*(.72+.22*hard));\n return over(v,dkLight(abs(abs(x)-w),.009,g*(1.-smoothstep(.94,1.02,abs(y)))*(.40+.28*hard),1.+hard,dkPurple()));\n}\nvec4 dkOrb(vec2 p,vec2 c,float r,float e,float t,float power){\n if(r<=.003||e<=.001)return vec4(0.);\n vec2 z=(p-c)/r;float d=length(z),a=atan(z.y,z.x),n=fb(z*5.+dir2(t*TAU)*.4);\n float rim=d-1.+.037*sin(a*7.+t*TAU*2.);\n vec4 v=vec4(mix(vec3(.009,.004,.021),vec3(.22,.07,.43),n*n),(1.-smoothstep(.88,1.03,d))*e*.98);\n return over(v,dkLight(rim*r,.009+.004*power,e*.9,power,dkPurple()));\n}\nvec4 dkVortex(vec2 p,float t,float r,float e,float power){\n if(r<=.003||e<=.001)return vec4(0.);\n vec2 z=p/vec2(1.,.86);float d=length(z),a=atan(z.y,z.x),n=fb(z*6.+dir2(t*TAU)*.4);\n float spiral=5.*(a+4.9*d)-t*TAU*9.+1.5*n;float arm=pow(.5+.5*cos(spiral),2.);\n float env=smoothstep(r*.7,r*1.3,d)*(1.-smoothstep(.66,.97,d))*e;\n vec4 v=vec4(mix(vec3(.035,.012,.070),dkPurple(),arm*.66),sat(env*(.25+.65*arm)));\n return over(v,dkOrb(p,vec2(0.),r,e,t,power));\n}\nvec4 dkQuiet(vec2 p,float t,float g,float rank0){\n if(g<=.001)return vec4(0.);\n vec2 r=vec2(.64+.10*rank0,.77+.08*rank0);vec2 z=p/max(r*g,vec2(.012));float d=length(z),a=atan(z.y,z.x);\n float veil=(1.-smoothstep(.80,1.02,d))*g;\n vec4 v=vec4(.027,.018,.055,veil*(.26+.21*rank0));\n float rim=(d-1.)*r.x*g;v=over(v,dkLight(rim,.008,g*.54,2.,dkGold()));\n for(int i=0;i<18;i++){float k=float(i),f=fract(t+hash(vec2(k,51.)));vec2 c=dir2(k*2.39996)*r*g*(.76+.13*hash(vec2(k,11.)));c.y+=.06*sin(f*TAU);v=over(v,dkLight(length(p-c),.006,g*(.30+.25*sin(f*TAU)),1.5,dkGold()));}\n return v;\n}\nvec4 dkEclipse(vec2 p,float t,float g,float power){\n if(g<=.001)return vec4(0.);float r=.62;\n vec4 v=vec4(.71,.66,.86,exp(-pow(length(p)/.57,3.))*g*.30);\n vec2 c=vec2(mix(-1.20,0.,g),.035*(1.-g));float d=length(p-c)-r;\n v=over(v,vec4(.009,.004,.022,(1.-smoothstep(-.014,.020,d))*g*.94));\n float edge=exp(-abs(d)/.021);return over(v,vec4(mix(dkPurple(),vec3(.87,.82,.98),edge),edge*g*.68));\n}\nvec4 dkAbsorb(vec2 p,float q,float power,float huge){\n float g=dkFast(phase(q,.07,.36)),h=pow(phase(q,.74,.94),2.6),e=g*(1.-smoothstep(.91,1.,q));\n vec4 v=dkGather(p,vec2(0.),q,.33,.87,power,dkPurple());\n for(int i=0;i<32;i++){float k=float(i),f=fract(q*(2.7+huge*1.6)+hash(vec2(k,13.)));float a=k*2.39996+q*TAU*1.7+f*2.7;vec2 d=dir2(a);float r=mix(.98,.08,f)*(1.-.83*h);vec2 c=d*r;float en=e*sin(3.14159*f);\n v=over(v,dkLight(seg(p,c,c+dir2(a-.27)*(.14+.08*huge)),.007,en,power,vec3(.66,.54,.94)));}\n if(huge>.5)v=over(v,dkVortex(p,q,max(.008,.25*g*(1.-h)),e,power));\n else v=over(v,dkCloud(p,vec2(0.),vec2(.32*g*(1.-h)),q,e,1.,dkPurple()));\n return v;\n}\n";
