const crownFastFlight="\nvec4 crownShot(vec2 p,vec2 from,vec2 target,vec2 axis,float q,float t){\n float f=phase(q,.24,.383333);\n if(q<.24||f>=1.)return vec4(0.);\n vec2 dir=normalize(target-from);\n float travel=f;\n vec2 pos=mix(from,target,travel);\n vec4 w=crownDiamond(p,pos,dir,crownLength,crownWidth,t,0.);\n w.rgb=mix(w.rgb,vec3(.96,.99,1.),.60);\n w.a*=1.-smoothstep(.91,1.,f);\n vec2 prev=mix(from,target,max(0.,f-.58));\n float dist=seg(p,prev,pos);\n float gate0=smoothstep(0.,.06,f)*(1.-smoothstep(.88,1.,f));\n float halo=exp(-dist/.038)*gate0;\n float core=exp(-dist/.012)*gate0;\n vec4 v=vec4(vec3(.57,.79,1.),halo*.44);\n v=over(v,vec4(vec3(.91,.98,1.),core*.88));\n return over(v,w);\n}\nvec4 crownImpact(vec2 p,vec2 target,float q,float t){\n float f=phase(q,.383333,.70);if(f<=0.||f>=1.)return vec4(0.);\n float flash=exp(-f*14.)*exp(-pow(length(p-target)/.092,2.)*2.);\n vec4 v=vec4(vec3(.91,.98,1.),flash*.85);\n for(int i=0;i<6;i++){float k=float(i);vec2 dir=dir2(k*2.39996),c=target+dir*.17*(1.-pow(1.-f,3.));\n vec4 w=crownDiamond(p,c,dir,.076*(1.-f),.016,t,k);w.a*=sin(3.14159*f);v=over(v,w);}\n return v;\n}\n";
